  original=lines(old/'C_LOSSES.jsonl');formula=js(root/'FORMULA_ACCEPTED.json');assert formula['status']=='passed' and formula['formal_parameter_unchanged'];u=np.array([1.,-2.,3.,.25],np.float32);v=np.array([.5,-1.,2.,-.25],np.float32);assert .5*np.square(u-v).sum()==1.25
